import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
dfs = {}
for i in [1,2,4,5,6,7,8,9,10]:
    try:
        dfs[i] = pd.read_csv(f"results_v8_qwen27b_nautilus/v7_watertreatment_dosewin_interior_dose_sympto_10000299_data/experiment_{i}.csv")
        dfs[i]['exp_id'] = i
        print(f"\n=== Experiment {i} ===")
        print(dfs[i].describe().loc[['mean','std']].T)
    except Exception as e:
        print(f"Experiment {i} not available: {e}")

# Combine all data
all_data = pd.concat(dfs.values(), ignore_index=True)
print(f"\n\n=== ALL DATA: {len(all_data)} rows ===")
print(all_data.columns.tolist())

# Check what columns we have
for col in all_data.columns:
    if all_data[col].dtype in ['float64', 'int64']:
        print(f"\n{col}: mean={all_data[col].mean():.2f}, std={all_data[col].std():.2f}")

# Group by experiment and show key variables
print("\n\n=== Summary by experiment ===")
key_vars = [c for c in all_data.columns if c not in ['exp_id']]
for i in sorted(dfs.keys()):
    df = dfs[i]
    summary = {}
    for c in key_vars:
        if c in df.columns and df[c].dtype in ['float64', 'int64']:
            summary[c] = df[c].mean()
    print(f"Exp {i}: {summary}")

# Look for MaskingAdditive effect - compare exps with and without
masking_exps = [7, 8, 10]  # experiments with MaskingAdditive
non_masking = [1, 2, 4, 5, 6, 9]

for exp_id in masking_exps:
    if exp_id in dfs:
        df = dfs[exp_id]
        mask_col = [c for c in df.columns if 'ask' in c.lower() or 'additive' in c.lower() or 'chel' in c.lower()]
        flush_col = [c for c in df.columns if 'lush' in c.lower() or 'flush' in c.lower()]
        clarity_col = [c for c in df.columns if 'larit' in c.lower() or 'Clarity' in c]
        print(f"\nExp {exp_id} - Masking col: {mask_col}, Flush col: {flush_col}, Clarity col: {clarity_col}")
        if mask_col:
            print(f"  Masking value: {df[mask_col[0]].mean():.2f}")
        if flush_col:
            print(f"  Flush value: {df[flush_col[0]].mean():.2f}")
        if clarity_col:
            print(f"  Clarity: {df[clarity_col[0]].mean():.2f}")
